  formulas: [
    { name: 'Minutes per mark', tex: '\\text{min per mark}=\\frac{T-\\text{review}}{\\text{total marks}}=\\frac{170}{122}\\approx1.39', note: 'Question time = marks times this figure.' },
    { name: 'Quartile rank, $(n+1)p$ rule', tex: '\\text{rank}=p\\,(n+1),\\qquad P=x_{\\lfloor r\\rfloor}+(r-\\lfloor r\\rfloor)(x_{\\lfloor r\\rfloor+1}-x_{\\lfloor r\\rfloor})', note: 'Class notes convention; NumPy: method="weibull".' },
    { name: 'NumPy linear percentile', tex: '\\text{position}=1+p\\,(n-1)', note: 'Default of np.percentile (1-based position, then interpolate).' },
    { name: 'IQR', tex: '\\text{IQR}=Q_3-Q_1' },
    { name: 'Population and sample variance', tex: '\\sigma^2=\\frac{\\sum(x-\\mu)^2}{N},\\qquad s^2=\\frac{\\sum(x-\\bar{x})^2}{n-1}' },
    { name: 'Binomial probability', tex: 'P(X=k)=\\binom{n}{k}p^k(1-p)^{n-k}' },
    { name: 'z confidence interval', tex: '\\bar{x}\\pm z_{\\alpha/2}\\,\\frac{\\sigma}{\\sqrt{n}}', note: '95%: 1.96, 90%: 1.645, 99%: 2.576.' },
    { name: 'One-way ANOVA', tex: 'F=\\frac{SSB/(k-1)}{SSW/(N-k)},\\qquad SST=SSB+SSW' },
    { name: 'Chi-square statistic', tex: '\\chi^2=\\sum\\frac{(O-E)^2}{E},\\quad E=\\frac{\\text{row}\\times\\text{col}}{\\text{total}},\\quad df=(r-1)(c-1)', note: 'Goodness of fit: df = categories - 1.' },
    { name: 'Characteristic equation (2 by 2)', tex: '\\lambda^2-(\\operatorname{tr}A)\\lambda+\\det A=0' },
    { name: 'Hessian', tex: 'H=\\begin{pmatrix}f_{xx}&f_{xy}\\\\f_{yx}&f_{yy}\\end{pmatrix},\\qquad f\'\'(x)=[f_{xx}]\\text{ for one variable}' },
  ],
